CREATE TABLE sale_products(id TEXT PRIMARY KEY,coffee_id TEXT NOT NULL REFERENCES coffees(id),package_id TEXT NOT NULL REFERENCES packages(id),UNIQUE(coffee_id,package_id));
INSERT OR IGNORE INTO sale_products SELECT 'legacy:'||coffee_id||':'||package_id,coffee_id,package_id FROM variants WHERE kind='coffee' AND coffee_id IS NOT NULL AND package_id IS NOT NULL;
CREATE TABLE sale_catalog(source TEXT NOT NULL CHECK(source IN ('shopify','square')),external_id TEXT NOT NULL,name TEXT NOT NULL DEFAULT '',variation TEXT NOT NULL DEFAULT '',sku TEXT NOT NULL DEFAULT '',weight_mg INTEGER,unit TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL DEFAULT 'unresolved' CHECK(kind IN ('unresolved','coffee','noncoffee')),product_id TEXT REFERENCES sale_products(id),review INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(source,external_id));
INSERT INTO sale_catalog(source,external_id,name,sku,kind,product_id) SELECT 'shopify',v.id,COALESCE((SELECT l.title FROM lines l WHERE l.variant_id=v.id LIMIT 1),v.sku),v.sku,v.kind,(SELECT p.id FROM sale_products p WHERE p.coffee_id=v.coffee_id AND p.package_id=v.package_id) FROM variants v WHERE v.id NOT LIKE 'wholesale:%';
CREATE TABLE square_locations(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL);
CREATE TABLE square_sales(id TEXT PRIMARY KEY,location_id TEXT NOT NULL,version INTEGER NOT NULL,completed_at TEXT NOT NULL,updated_at TEXT NOT NULL,state TEXT NOT NULL,payload TEXT NOT NULL,posted_payload TEXT,status TEXT NOT NULL DEFAULT 'preview',detail TEXT NOT NULL DEFAULT '',movement_id TEXT UNIQUE REFERENCES movements(id));
CREATE TABLE square_sale_picks(id INTEGER PRIMARY KEY AUTOINCREMENT,sale_id TEXT NOT NULL REFERENCES square_sales(id),line_uid TEXT NOT NULL,stock_id TEXT NOT NULL REFERENCES stocks(id),quantity_mg INTEGER NOT NULL,overfill_mg INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER square_picks_no_update BEFORE UPDATE ON square_sale_picks BEGIN SELECT RAISE(ABORT,'Sale picks are immutable'); END;
CREATE TRIGGER square_picks_no_delete BEFORE DELETE ON square_sale_picks BEGIN SELECT RAISE(ABORT,'Sale picks are immutable'); END;
INSERT INTO settings VALUES ('square_enabled','false'),('square_start_at','null'),('square_location_id','null'),('square_poll_seconds','60');
